package com.fitlife.mfe.personal.bff.controller;
import com.fasterxml.jackson.databind.JsonNode;import com.fitlife.mfe.personal.bff.service.AuthCookieService;import com.fitlife.mfe.personal.bff.service.PersonaisBffService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/bff") public class PersonaisBffController{private final PersonaisBffService service;private final AuthCookieService auth;public PersonaisBffController(PersonaisBffService s,AuthCookieService a){service=s;auth=a;}@GetMapping("/usuario/me")public JsonNode usuario(@CookieValue(value="FITLIFE_AUTH",required=false)String t){return service.usuario(auth.usuarioId(t),t);}@GetMapping("/personais")public JsonNode listar(@CookieValue(value="FITLIFE_AUTH",required=false)String t){return service.listar(t);}@PostMapping("/personais/{id}/contato")public JsonNode contatar(@PathVariable String id,@CookieValue(value="FITLIFE_AUTH",required=false)String t){return service.contatar(id,auth.usuarioId(t),t);}}
